export class Hoa10Service {
  static getLessons(chapter?: number): Hoa10Lesson[] {
    if (!chapter) return HOA10_LESSONS;
    return HOA10_LESSONS.filter(l => l.chapter === chapter);
  }

  static getLessonById(id: string): Hoa10Lesson | undefined {
    return HOA10_LESSONS.find(l => l.id === id);
  }

  static getExams(chapter?: number): Hoa10Exam[] {
    if (!chapter) return HOA10_EXAMS;
    return HOA10_EXAMS.filter(e => e.chapter === chapter);
  }

  static getExamById(id: string): Hoa10Exam | undefined {
    return HOA10_EXAMS.find(e => e.id === id);
  }

  static getHandbook() {
    return HOA10_HANDBOOK;
  }
}

export function getHoa10UserProgress(): Hoa10UserProgress {
  try {
    const raw = localStorage.getItem('hoa10_progress');
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return {
    completedLessons: [],
    examAttempts: {},
    totalXp: 120,
    streakDays: 1
  };
}

export function calculateHoa10ExamScore(questionsInput: any, userAnswers: Record<string | number, any>) {
  const questions: Hoa10Question[] = Array.isArray(questionsInput) ? questionsInput : (questionsInput?.questions || []);
  let rawScore = 0;
  let correctCount = 0;
  const breakdown: Record<number, any> = { 1: { correct: 0, total: 0 }, 2: { correct: 0, total: 0 }, 3: { correct: 0, total: 0 } };

  questions.forEach(q => {
    const part = q.part || 1;
    if (!breakdown[part]) breakdown[part] = { correct: 0, total: 0 };
    breakdown[part].total++;

    const ans = userAnswers[q.id] ?? userAnswers[q.number] ?? userAnswers[q.displayNumber];
    if (part === 1) {
      const correctOpt = q.options?.find(o => o.isCorrect)?.letter || q.correctAnswer;
      if (ans && correctOpt && String(ans).trim().toUpperCase() === String(correctOpt).trim().toUpperCase()) {
        rawScore += 0.25;
        correctCount++;
        breakdown[1].correct++;
      }
    } else if (part === 2) {
      if (typeof ans === 'object' && ans !== null) {
        let subCorrect = 0;
        q.options?.forEach(opt => {
          const userVal = ans[opt.letter] ?? ans[opt.letter.toLowerCase()];
          const expVal = opt.isCorrect !== undefined ? opt.isCorrect : (String(opt.text).includes('Đúng') || String(opt.text).includes('đúng'));
          if (userVal !== undefined && Boolean(userVal) === Boolean(expVal)) {
            subCorrect++;
          }
        });
        if (subCorrect === 1) rawScore += 0.1;
        else if (subCorrect === 2) rawScore += 0.25;
        else if (subCorrect === 3) rawScore += 0.5;
        else if (subCorrect === 4) { rawScore += 1.0; correctCount++; }
        if (subCorrect === 4) breakdown[2].correct++;
      }
    } else if (part === 3) {
      const expected = String(q.correctAnswer || '').trim().toLowerCase().replace(',', '.');
      const userText = String(ans || '').trim().toLowerCase().replace(',', '.');
      if (userText && (userText === expected || expected.includes(userText))) {
        rawScore += 0.5;
        correctCount++;
        breakdown[3].correct++;
      }
    }
  });

  const finalScore = Math.min(10, Math.round(rawScore * 10) / 10);
  return {
    score: finalScore,
    correctCount,
    totalQuestions: questions.length,
    breakdown
  };
}

export function getHoa10ExamHistory(examId?: string): Hoa10ExamAttempt[] {
  try {
    const raw = localStorage.getItem('hoa10_exam_history');
    if (raw) {
      const list: Hoa10ExamAttempt[] = JSON.parse(raw);
      if (examId) return list.filter(a => a.examId === examId);
      return list;
    }
  } catch (e) {}
  return [];
}

export function saveHoa10ExamAttempt(attempt: Hoa10ExamAttempt) {
  try {
    const list = getHoa10ExamHistory();
    list.unshift(attempt);
    localStorage.setItem('hoa10_exam_history', JSON.stringify(list.slice(0, 30)));
    
    // Cập nhật tiến trình
    const prog = getHoa10UserProgress();
    const cur = prog.examAttempts[attempt.examId] || { bestScore: 0, lastScore: 0, attempts: 0, passed: false };
    cur.attempts += 1;
    cur.lastScore = attempt.score;
    if (attempt.score > cur.bestScore) cur.bestScore = attempt.score;
    if (attempt.score >= 5.0) cur.passed = true;
    prog.examAttempts[attempt.examId] = cur;
    prog.totalXp += Math.round(attempt.score * 20);
    localStorage.setItem('hoa10_progress', JSON.stringify(prog));
  } catch (e) {}
}

export function shuffleHoa10Exam(exam: Hoa10Exam): Hoa10Exam {
  const qList = [...exam.questions];
  const p1 = qList.filter(q => q.part === 1);
  const p2 = qList.filter(q => q.part === 2);
  const p3 = qList.filter(q => q.part === 3);

  const shuffleArray = (arr: any[]) => {
    const res = [...arr];
    for (let i = res.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [res[i], res[j]] = [res[j], res[i]];
    }
    return res;
  };

  const shuffledP1 = shuffleArray(p1).map(q => {
    if (!q.options) return q;
    return { ...q, options: shuffleArray(q.options) };
  });

  const combined = [...shuffledP1, ...p2, ...p3];
  combined.forEach((q, idx) => {
    q.displayNumber = idx + 1;
  });

  return {
    ...exam,
    questions: combined
  };
}

export function getHoa10RankTitle(xp: number): string {
  if (xp >= 1500) return 'Bậc Thầy Hóa Học 🏆';
  if (xp >= 1000) return 'Chiến Thần Đạt Điểm 9+ 💎';
  if (xp >= 600) return 'Cao Thủ Hóa Học ⚡';
  if (xp >= 300) return 'Học Viên Chuyên Cần 📚';
  return 'Tân Binh Học Hóa 🌱';
}
